REPLICAS = ("r0", "r1", "r2")      # r0 = leader
ACK_STATE = {0: 0, 1: 2, "all": 3}
DURABLE = {
    1: frozenset(),                                    # 只进了 leader 的 page cache -> 宕机即丢
    2: frozenset({"r0"}),                              # leader 已 fsync
    3: frozenset({"r0", "r1", "r2"}),                  # 全 ISR 已 fsync
}
STATE_NAME = {1: "leader 缓存后（未落盘）", 2: "leader fsync 后", 3: "全 ISR 同步后"}


def subsets():
    out = []
    for mask in range(1, 8):
        out.append(frozenset(REPLICAS[i] for i in range(3) if (mask >> i) & 1))
    return out


def ack_state(acks):
    return ACK_STATE[acks]


def lost_scenarios(acks):
    """枚举「已 ack 但数据实际丢失」的 (崩溃阶段, 宕机副本集合) 场景数。"""
    st = ack_state(acks)
    total = 0
    samples = []
    for phase in (1, 2, 3):
        if phase < st:
            continue                      # 崩溃发生在 ack 之前 -> 生产者知道失败, 可重试, 不算丢
        durable = DURABLE[phase]
        for crashed in subsets():
            survivors = set(REPLICAS) - crashed
            if not (durable & survivors):
                total += 1
                if len(samples) < 2:
                    samples.append("%s / 宕机=%s" % (STATE_NAME[phase], "+".join(sorted(crashed))))
    return total, samples


ALL = len(subsets()) * 3
print("=== acks 三档的「已确认却丢失」场景数（RF=3，枚举 %d 种崩溃组合）===" % ALL)
print("%-12s %14s %10s" % ("acks", "危险场景数", "占比"))
for acks in (0, 1, "all"):
    n, samples = lost_scenarios(acks)
    print("%-12s %14d %9.1f%%" % (str(acks), n, 100.0 * n / ALL))
print()
for acks in (0, 1, "all"):
    n, samples = lost_scenarios(acks)
    print("acks=%-4s 最典型危险场景:" % acks)
    for s in samples:
        print("      ", s)
